<?php
require_once __DIR__.'/../../includes/init.php';require_role('admin');require_once __DIR__.'/../../includes/layout.php';$pdo=db();$q=trim((string)($_GET['q']??''));$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');$page=page_number();$lim=15;$w=[];$p=[];if($q!==''){$w[]='(l.aktivitas LIKE ? OR u.username LIKE ? OR u.nama_lengkap LIKE ?)';array_push($p,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}if($from!==''&&$to!==''){try{[$a,$b]=valid_date_range($from,$to);$w[]='l.waktu_aktivitas BETWEEN ? AND ?';array_push($p,$a,$b);}catch(Throwable $e){$error=$e->getMessage();}}elseif($from!==''||$to!==''){$error='Isi tanggal mulai dan akhir.';}$ws=$w?' WHERE '.implode(' AND ',$w):'';$c=$pdo->prepare('SELECT COUNT(*) FROM tb_log_aktivitas l JOIN tb_user u ON u.id_user=l.id_user'.$ws);$c->execute($p);$total=(int)$c->fetchColumn();$s=$pdo->prepare('SELECT l.*,u.nama_lengkap,u.username,u.role FROM tb_log_aktivitas l JOIN tb_user u ON u.id_user=l.id_user'.$ws.' ORDER BY l.id_log DESC LIMIT '.$lim.' OFFSET '.(($page-1)*$lim));$s->execute($p);$rows=$s->fetchAll();render_header('Log Aktivitas','aktivitas');?>
<div class="page-intro"><div><h2>Log aktivitas</h2><p>Riwayat operasi penting untuk kebutuhan audit. Log tidak dapat dihapus dari aplikasi.</p></div></div><?php if(!empty($error)): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><form method="get" class="filter-row"><div class="field" style="min-width:220px"><label>Pencarian</label><input name="q" value="<?= h($q) ?>" placeholder="Aktivitas atau pengguna"></div><div class="field"><label>Dari tanggal</label><input name="from" type="date" value="<?= h($from) ?>"></div><div class="field"><label>Sampai tanggal</label><input name="to" type="date" value="<?= h($to) ?>"></div><button class="btn btn-primary">Filter</button><a class="btn btn-secondary" href="<?= h(url('admin/aktivitas/index.php')) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Role</th><th>Aktivitas</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h(tanggal($r['waktu_aktivitas'])) ?></td><td class="td-main"><?= h($r['nama_lengkap']) ?><div class="muted">@<?= h($r['username']) ?></div></td><td><?= h(ucfirst($r['role'])) ?></td><td><?= h($r['aktivitas']) ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="4"><div class="empty-state">Belum ada log yang cocok.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span><?= $total ?> aktivitas ditemukan</span><?= pagination($total,$lim,$page,url('admin/aktivitas/index.php?q='.rawurlencode($q).'&from='.rawurlencode($from).'&to='.rawurlencode($to))) ?></div></section><?php render_footer(); ?>